bash: {"command": "{
  echo "## Версия ОС (uname -a)"; uname -a;
  echo "## Ядро (uname -r)"; uname -r;
  echo "## Архитектура (uname -m)"; uname -m;
  echo "## Uptime"; uptime -p;
  echo "## Дата/время (UTC)"; date --utc;
  echo "## Часовой пояс"; timedatectl show -p Timezone --value 2>/dev/null || echo 'n/a';
  echo "## Диск (/)"; df -hT /;
  echo "## Порты (top 20)"; ss -tulpen 2>/dev/null | head -n 20 || netstat -tulpen 2>/dev/null | head -n 20;
  echo "## Переменные прокси"; env | grep -i -E 'proxy|http_proxy|https_proxy|no_proxy' 2>/dev/null || true;
  echo "## Процессы (top-10 по CPU)"; ps -eo pid,ppid,cmd,%cpu --sort=-%cpu | head -n 11;
} > аудит_впс.md
"}
